import{_ as t,o,c as i,aa as a}from"./chunks/framework.BAs_AphD.js";const r="/buildary-help-preview/media/cs/diary/certmgr.msc.png",n="/buildary-help-preview/media/cs/diary/certmgr.msc2.png",l="/buildary-help-preview/media/cs/diary/certmgr.msc3.png",s="/buildary-help-preview/media/cs/diary/certmgr.msc4.png",g=JSON.parse('{"title":"Certifikát v mobilu","description":"","frontmatter":{"title":"Certifikát v mobilu","wiki":"cs:diary:m_certificate"},"headers":[],"relativePath":"diary/m_certificate.md","filePath":"diary/m_certificate.md","lastUpdated":1794209661000}'),p={name:"diary/m_certificate.md"};function c(d,e,m,u,v,f){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="certifikat-v-mobilu" tabindex="-1">Certifikát v mobilu <a class="header-anchor" href="#certifikat-v-mobilu" aria-label="Permalink to &quot;Certifikát v mobilu&quot;">​</a></h1><p>Chcete-li v mobilní aplikaci podepisovat kvalifikovaným certifikátem, musíte ho mít v telefonu jako soubor PFX včetně privátního klíče. Pokud máte certifikát v počítači s Windows, vyexportujte ho a soubor přeneste do telefonu.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/mobilni-aplikace-denik">Psát deník v mobilu</a> v Akademii.</p><h2 id="vyexportovat-certifikat-z-windows" tabindex="-1">Vyexportovat certifikát z Windows <a class="header-anchor" href="#vyexportovat-certifikat-z-windows" aria-label="Permalink to &quot;Vyexportovat certifikát z Windows&quot;">​</a></h2><ol><li>Do hledání na liště Windows napište <strong>certmgr.msc</strong> a nalezený program otevřete.</li><li>Otevřete <strong>Osobní</strong> → <strong>Certifikáty</strong> a vyberte certifikát, kterým podepisujete. Klikněte na něj pravým tlačítkem a zvolte <strong>Všechny úkoly</strong> → <strong>Exportovat</strong>.</li><li>V průvodci exportem zvolte <strong>Ano, exportovat privátní klíč</strong>.</li><li>Jako formát vyberte <strong>Personal Information Exchange – PKCS č. 12 (PFX)</strong>.</li><li>Zvolte heslo a název souboru a soubor uložte tam, kde ho snadno najdete. Heslo si zapamatujte – budete ho zadávat v mobilu.</li></ol><div class="gallery"><figure class="shot"><img src="'+r+'" alt="Vyhledání programu certmgr.msc ve Windows" loading="lazy"><figcaption>Krok 1</figcaption></figure><figure class="shot"><img src="'+n+'" alt="Správce certifikátů: Osobní, Certifikáty, Všechny úkoly, Exportovat" loading="lazy"><figcaption>Krok 2</figcaption></figure><figure class="shot"><img src="'+l+'" alt="Průvodce exportem certifikátu: Ano, exportovat privátní klíč" loading="lazy"><figcaption>Krok 3</figcaption></figure><figure class="shot"><img src="'+s+'" alt="Průvodce exportem certifikátu: formát PFX" loading="lazy"><figcaption>Krok 4</figcaption></figure></div><p>Pokud volbu <strong>Ano, exportovat privátní klíč</strong> nejde vybrat, certifikát byl vydán jako neexportovatelný a do telefonu ho tímto postupem nepřenesete. Obraťte se na vydavatele certifikátu.</p><h2 id="prenest-soubor-do-telefonu" tabindex="-1">Přenést soubor do telefonu <a class="header-anchor" href="#prenest-soubor-do-telefonu" aria-label="Permalink to &quot;Přenést soubor do telefonu&quot;">​</a></h2><p>Soubor PFX přeneste do telefonu – připojte telefon k počítači kabelem a soubor do něj zkopírujte, nebo použijte sdílené úložiště.</p><h2 id="nahrat-certifikat-do-aplikace" tabindex="-1">Nahrát certifikát do aplikace <a class="header-anchor" href="#nahrat-certifikat-do-aplikace" aria-label="Permalink to &quot;Nahrát certifikát do aplikace&quot;">​</a></h2><ol><li>V mobilní aplikaci otevřete menu, klepněte na <strong>Nastavení</strong> a pak na <strong>Nastavení podpisu</strong>.</li><li>Zvolte <strong>Kvalifikovaný certifikát</strong>.</li><li>Vyberte v telefonu soubor PFX a zadejte heslo, které jste zvolili při exportu.</li><li>Nastavte vzhled podpisu a potvrďte tlačítkem <strong>OK</strong> vpravo nahoře.</li></ol><p>Další možnosti podpisu v mobilu popisuje <a href="/buildary-help-preview/diary/m_signing">Podepisování v mobilu</a>.</p>',12)])])}const h=t(p,[["render",c]]);export{g as __pageData,h as default};
